def prepare_ui_node(node: dict) -> dict:
    """Encode explicit nullable-offset presence for Unity JsonUtility."""
    result = dict(node)
    for key in ('offset_min', 'offset_max'):
        present = node.get(key) is not None
        result["has_" + key] = present
        if not present:
            result.pop(key, None)
    result["children"] = [prepare_ui_node(child) for child in node.get("children", [])]
    return result
